import{_ as e,c as i,o as n,ag as o}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Introducción","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/introduction.md","filePath":"es/guide/introduction.md","lastUpdated":1794112334000}'),r={name:"es/guide/introduction.md"};function s(t,a,d,c,l,u){return n(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="introduccion" tabindex="-1">Introducción <a class="header-anchor" href="#introduccion" aria-label="Permalink to &quot;Introducción&quot;">​</a></h1><h2 id="acerca-de-nicasa" tabindex="-1">Acerca de Nicasa <a class="header-anchor" href="#acerca-de-nicasa" aria-label="Permalink to &quot;Acerca de Nicasa&quot;">​</a></h2><p>Nicasa es un visor de imágenes de escritorio moderno y una herramienta de captura de pantalla diseñada para la velocidad, la sencillez y unas capacidades de edición potentes. Creada exclusivamente para macOS, Nicasa lleva a tu escritorio una experiencia de visualización fluida y moderna.</p><h2 id="funciones-principales" tabindex="-1">Funciones principales <a class="header-anchor" href="#funciones-principales" aria-label="Permalink to &quot;Funciones principales&quot;">​</a></h2><h3 id="🖼️-una-mejor-forma-de-ver-imagenes" tabindex="-1">🖼️ <strong>Una mejor forma de ver imágenes</strong> <a class="header-anchor" href="#🖼️-una-mejor-forma-de-ver-imagenes" aria-label="Permalink to &quot;🖼️ **Una mejor forma de ver imágenes**&quot;">​</a></h3><p>Abre imágenes al instante con una interfaz limpia y enfocada. Sin distracciones, sin desorden: solo tu contenido, presentado con elegancia en el momento en que lo abres.</p><h3 id="📸-capturas-de-pantalla" tabindex="-1">📸 <strong>Capturas de pantalla</strong> <a class="header-anchor" href="#📸-capturas-de-pantalla" aria-label="Permalink to &quot;📸 **Capturas de pantalla**&quot;">​</a></h3><p>Captura cualquier parte de la pantalla en segundos. Con herramientas de captura rápidas y precisas integradas en Nicasa, guardar y compartir ideas visuales nunca ha sido tan fácil.</p><h3 id="🤖-editor-de-imagenes-con-ia" tabindex="-1">🤖 <strong>Editor de imágenes con IA</strong> <a class="header-anchor" href="#🤖-editor-de-imagenes-con-ia" aria-label="Permalink to &quot;🤖 **Editor de imágenes con IA**&quot;">​</a></h3><p>Mejora y perfecciona tus imágenes con herramientas de IA potentes. Desde ajustes rápidos hasta edición inteligente, Nicasa te ayuda a transformar imágenes sin esfuerzo.</p><h3 id="🔍-modo-superposicion-transparente" tabindex="-1">🔍 <strong>Modo superposición transparente</strong> <a class="header-anchor" href="#🔍-modo-superposicion-transparente" aria-label="Permalink to &quot;🔍 **Modo superposición transparente**&quot;">​</a></h3><p>Una herramienta poderosa para diseñadores y artistas: fija una imagen por encima de todas las ventanas con transparencia ajustable, perfecto para calcar, consultar referencias y comparar interfaces.</p><h3 id="🌐-integracion-con-la-extension-de-chrome" tabindex="-1">🌐 <strong>Integración con la extensión de Chrome</strong> <a class="header-anchor" href="#🌐-integracion-con-la-extension-de-chrome" aria-label="Permalink to &quot;🌐 **Integración con la extensión de Chrome**&quot;">​</a></h3><p>Conéctate sin problemas con la extensión de Chrome de Nicasa para ver todas las imágenes de cualquier sitio web en un solo lugar. Extrae, explora y abre imágenes directamente en Nicasa para una experiencia más rápida e inmersiva.</p><h3 id="🎨-diseno-fluido-e-intuitivo" tabindex="-1">🎨 <strong>Diseño fluido e intuitivo</strong> <a class="header-anchor" href="#🎨-diseno-fluido-e-intuitivo" aria-label="Permalink to &quot;🎨 **Diseño fluido e intuitivo**&quot;">​</a></h3><p>Impulsada por tecnología de nueva generación, Nicasa ofrece transiciones fluidas, renderizado nítido y un diseño de interacción cuidado al detalle.</p><h2 id="requisitos-del-sistema" tabindex="-1">Requisitos del sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to &quot;Requisitos del sistema&quot;">​</a></h2><ul><li><strong>Sistema operativo</strong>: macOS 10.13 o posterior</li><li><strong>Memoria</strong>: 4 GB de RAM mínimo, 8 GB recomendados</li><li><strong>Almacenamiento</strong>: 54,5 MB para la instalación</li><li><strong>Pantalla</strong>: resolución mínima de 1280x720</li></ul><h2 id="idiomas-compatibles" tabindex="-1">Idiomas compatibles <a class="header-anchor" href="#idiomas-compatibles" aria-label="Permalink to &quot;Idiomas compatibles&quot;">​</a></h2><p>Nicasa admite una amplia variedad de idiomas, entre ellos inglés, chino simplificado, chino tradicional, japonés, francés, coreano, alemán, español, italiano, vietnamita, tailandés, hindi, turco, ruso, portugués, neerlandés, alemán (Suiza), finlandés, malayo, griego, noruego, indonesio, húngaro, danés y ucraniano.</p><h2 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h2><p>Si eres nuevo en Nicasa, empieza con la <a href="/es/guide/installation.html">Guía de instalación</a> para poner la aplicación en marcha en tu Mac.</p>',22)])])}const h=e(r,[["render",s]]);export{m as __pageData,h as default};
